-- Loca Loca: начальные справочные данные (44 достопримечательностей).
-- Экспортировано из пользовательского PostgreSQL backup 2026-11-06.
-- Включены только категории, страны, города и достопримечательности.
-- Пользователи, пароли, посещения, фотографии и личные заметки не экспортируются.
-- Повторный запуск не создаёт дубликаты.

SET standard_conforming_strings = on;

