INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Петергоф', 'Дворцово-парковый ансамбль на южном берегу Финского залива, известный фонтанами.', 'Создание резиденции Петра I началось в начале XVIII века. Большой дворец и система фонтанов стали центральными элементами ансамбля.', 59.884400::numeric, 29.908700::numeric, 'Дворцово-парковые ансамбли', 'Россия', 'Петергоф'),
    ('Эрмитаж', 'Один из крупнейших художественных и культурно-исторических музеев мира.', 'Музей ведёт историю с коллекции Екатерины II, начатой в 1764 году. Главный музейный комплекс расположен в зданиях Зимнего дворца и Малого, Старого и Нового Эрмитажа.', 59.939832::numeric, 30.314560::numeric, 'Музеи', 'Россия', 'Санкт-Петербург'),
    ('Собор Василия Блаженного', 'Православный храм на Красной площади, известный разноцветными куполами.', 'Построен в 1555–1561 годах по распоряжению Ивана IV в память о взятии Казани.', 55.752525::numeric, 37.623088::numeric, 'Религиозные сооружения', 'Россия', 'Москва'),
    ('Московский Кремль', 'Исторический архитектурный комплекс и действующая резиденция Президента России.', 'Крепость на Боровицком холме известна с XII века. Современный ансамбль стен и башен в основном сформировался в XV–XVII веках.', 55.752023::numeric, 37.617499::numeric, 'Исторические места', 'Россия', 'Москва'),
    ('Красная площадь', 'Главная площадь Москвы, расположенная у восточной стены Московского Кремля.', 'Сложилась как центральная торговая и общественная площадь города в конце XV века. Здесь находятся собор Василия Блаженного, Исторический музей и мавзолей.', 55.753930::numeric, 37.620795::numeric, 'Исторические места', 'Россия', 'Москва'),
    ('Лувр', 'Национальный музей Франции с обширной коллекцией произведений искусства.', 'Здание начиналось как крепость в конце XII века, позднее стало королевской резиденцией. Музей открылся для публики в 1793 году.', 48.860611::numeric, 2.337644::numeric, 'Музеи', 'Франция', 'Париж'),
    ('Эйфелева башня', 'Металлическая башня на Марсовом поле и один из самых узнаваемых символов Парижа.', 'Построена для Всемирной выставки 1889 года по проекту инженерной команды Гюстава Эйфеля.', 48.858370::numeric, 2.294481::numeric, 'Архитектура', 'Франция', 'Париж'),
    ('Колизей', 'Античный амфитеатр в центре Рима и один из крупнейших памятников Древнего Рима.', 'Строительство началось при императоре Веспасиане около 70 года н. э. и завершилось при Тите в 80 году.', 41.890210::numeric, 12.492231::numeric, 'Исторические места', 'Италия', 'Рим'),
    ('Саграда Фамилия', 'Католическая базилика, созданная по проекту Антонио Гауди.', 'Строительство началось в 1882 году. Гауди посвятил проекту значительную часть жизни; работы продолжаются и в XXI веке.', 41.403629::numeric, 2.174356::numeric, 'Религиозные сооружения', 'Испания', 'Барселона'),
    ('Статуя Свободы', 'Монумент на острове Свободы в Нью-Йоркской гавани.', 'Подарок Франции Соединённым Штатам, торжественно открытый в 1886 году. Статуя стала символом свободы и иммиграции.', 40.689249::numeric, -74.044500::numeric, 'Памятники', 'США', 'Нью-Йорк'),
    ('Биг-Бен', 'Обиходное название Большого колокола в часовой башне Вестминстерского дворца.', 'Часовая башня была завершена в середине XIX века. После реконструкции 2012–2017 годов получила официальное название Elizabeth Tower.', 51.500729::numeric, -0.124625::numeric, 'Архитектура', 'Великобритания', 'Лондон'),
    ('Афинский Акрополь', 'Древняя укреплённая возвышенность с выдающимися памятниками античной архитектуры.', 'Основные сооружения классического ансамбля, включая Парфенон, были построены в V веке до н. э. при Перикле.', 37.971532::numeric, 23.725749::numeric, 'Исторические места', 'Греция', 'Афины'),
    ('Золотой мост', 'Вантовый мост через бухту Золотой Рог во Владивостоке.', 'Мост открыли в 2012 году к саммиту АТЭС; он стал одной из узнаваемых частей городского пейзажа.', 43.111500::numeric, 131.898000::numeric, 'Архитектура', 'Россия', 'Владивосток'),
    ('Храм-на-Крови', 'Православный храм в Екатеринбурге, построенный на месте дома Ипатьева.', 'Храмовый комплекс был возведён в начале XXI века и освящён в 2003 году.', 56.842600::numeric, 60.609000::numeric, 'Религиозные сооружения', 'Россия', 'Екатеринбург'),
    ('Казанский кремль', 'Историческая крепость и архитектурный комплекс в центре Казани.', 'Кремль складывался на протяжении многих веков; его нынешний ансамбль включает памятники разных эпох.', 55.798500::numeric, 49.105400::numeric, 'Исторические места', 'Россия', 'Казань'),
    ('Кул-Шариф', 'Мечеть на территории Казанского кремля, один из символов Казани.', 'Современная мечеть открылась в 2005 году; её название напоминает о защитнике Казани Кул-Шарифе.', 55.798100::numeric, 49.105700::numeric, 'Религиозные сооружения', 'Россия', 'Казань'),
    ('Версальский дворец', 'Дворцово-парковый ансамбль к юго-западу от Парижа.', 'Дворец стал главной резиденцией французских королей при Людовике XIV в XVII веке.', 48.804900::numeric, 2.120400::numeric, 'Дворцово-парковые ансамбли', 'Франция', 'Версаль'),
    ('Триумфальная арка', 'Монумент на площади Шарля де Голля в Париже.', 'Арку начали строить по распоряжению Наполеона в 1806 году; строительство завершилось в 1836 году.', 48.873800::numeric, 2.295000::numeric, 'Памятники', 'Франция', 'Париж'),
    ('Нотр-Дам де Пари', 'Средневековый собор на острове Сите в центре Парижа.', 'Строительство готического собора началось в XII веке и продолжалось несколько столетий.', 48.853000::numeric, 2.349900::numeric, 'Религиозные сооружения', 'Франция', 'Париж'),
    ('Пизанская башня', 'Наклонная колокольня соборного комплекса на площади Чудес в Пизе.', 'Строительство башни началось в XII веке; наклон стал заметен ещё во время её возведения.', 43.723000::numeric, 10.396600::numeric, 'Архитектура', 'Италия', 'Пиза'),
    ('Собор Святого Марка', 'Собор на площади Сан-Марко в Венеции, известный мозаиками и византийским обликом.', 'Нынешний собор формировался с XI века и связан с историей Венецианской республики.', 45.434100::numeric, 12.339700::numeric, 'Религиозные сооружения', 'Италия', 'Венеция'),
    ('Собор Санта-Мария-дель-Фьоре', 'Кафедральный собор Флоренции с большим куполом Филиппо Брунеллески.', 'Строительство началось в 1296 году; купол был возведён в XV веке.', 43.773100::numeric, 11.256000::numeric, 'Религиозные сооружения', 'Италия', 'Флоренция'),
    ('Королевский Алькасар Севильи', 'Действующий королевский дворец и исторический комплекс в Севилье.', 'Дворец строился и перестраивался в разные эпохи; в его архитектуре сочетаются разные традиции.', 37.383100::numeric, -5.990300::numeric, 'Дворцово-парковые ансамбли', 'Испания', 'Севилья'),
    ('Музей Прадо', 'Национальный художественный музей Испании в Мадриде.', 'Музей открылся для публики в 1819 году и хранит коллекции испанского и европейского искусства.', 40.413800::numeric, -3.692100::numeric, 'Музеи', 'Испания', 'Мадрид'),
    ('Мост Золотые Ворота', 'Подвесной мост через пролив Золотые Ворота в Сан-Франциско.', 'Мост открылся в 1937 году и стал одним из символов города.', 37.819900::numeric, -122.478300::numeric, 'Архитектура', 'США', 'Сан-Франциско'),
    ('Мемориал Линкольна', 'Мемориал в честь президента Авраама Линкольна в Вашингтоне.', 'Здание мемориала было открыто в 1922 году.', 38.889300::numeric, -77.050200::numeric, 'Памятники', 'США', 'Вашингтон'),
    ('Британский музей', 'Музей истории и культуры народов мира в Лондоне.', 'Британский музей открылся для публики в 1759 году.', 51.519400::numeric, -0.127000::numeric, 'Музеи', 'Великобритания', 'Лондон'),
    ('Тауэрский мост', 'Разводной мост через Темзу рядом с Лондонским Тауэром.', 'Мост был открыт в 1894 году и стал важной частью инфраструктуры Лондона.', 51.505500::numeric, -0.075400::numeric, 'Архитектура', 'Великобритания', 'Лондон'),
    ('Сиднейский оперный театр', 'Оперный театр и концертный комплекс на берегу гавани Сиднея.', 'Здание, спроектированное Йорном Утзоном, открылось в 1973 году.', -33.856800::numeric, 151.215300::numeric, 'Архитектура', 'Австралия', 'Сидней'),
    ('Дворец Шёнбрунн', 'Дворцово-парковый комплекс в Вене.', 'Шёнбрунн был летней резиденцией Габсбургов; его ансамбль сформировался в XVII–XVIII веках.', 48.184500::numeric, 16.312200::numeric, 'Дворцово-парковые ансамбли', 'Австрия', 'Вена'),
    ('Статуя Христа-Искупителя', 'Монумент на вершине горы Корковаду с видом на Рио-де-Жанейро.', 'Статуя была открыта в 1931 году и стала одним из символов города.', -22.951900::numeric, -43.210500::numeric, 'Памятники', 'Бразилия', 'Рио-де-Жанейро'),
    ('Музейный остров', 'Комплекс музеев на острове реки Шпрее в центре Берлина.', 'Музеи комплекса создавались в XIX и XX веках; ансамбль включён в список Всемирного наследия ЮНЕСКО.', 52.516900::numeric, 13.401000::numeric, 'Музеи', 'Германия', 'Берлин'),
    ('Бранденбургские ворота', 'Монументальные городские ворота в центре Берлина.', 'Ворота были построены в конце XVIII века и стали одним из символов Берлина.', 52.516300::numeric, 13.377700::numeric, 'Исторические места', 'Германия', 'Берлин'),
    ('Пирамиды Гизы', 'Комплекс древнеегипетских пирамид на плато Гиза.', 'Крупнейшая пирамида комплекса была построена для фараона Хуфу в XXVI веке до н. э.', 29.979200::numeric, 31.134200::numeric, 'Археологические памятники', 'Египет', 'Гиза'),
    ('Тадж-Махал', 'Мавзолей из белого мрамора в городе Агра.', 'Комплекс был построен в XVII веке по приказу падишаха Шах-Джахана.', 27.175100::numeric, 78.042100::numeric, 'Исторические места', 'Индия', 'Агра'),
    ('Великая Китайская стена (Мутяньюй)', 'Участок Великой Китайской стены в районе Мутяньюй к северу от Пекина.', 'Участок Мутяньюй был построен и укреплён в период династии Мин.', 40.431900::numeric, 116.570400::numeric, 'Исторические места', 'Китай', 'Хуайжоу'),
    ('Запретный город', 'Дворцовый комплекс в центре Пекина, известный также как Гугун.', 'Комплекс служил резиденцией китайских императоров династий Мин и Цин; строительство началось в начале XV века.', 39.916300::numeric, 116.397200::numeric, 'Исторические места', 'Китай', 'Пекин'),
    ('Теотиуакан', 'Археологический комплекс с пирамидами Солнца и Луны.', 'Город возник задолго до ацтеков и был одним из крупнейших центров Мезоамерики.', 19.692500::numeric, -98.843800::numeric, 'Археологические памятники', 'Мексика', 'Сан-Хуан-Теотиуакан'),
    ('Рейксмюсеум', 'Национальный музей Нидерландов в Амстердаме.', 'Музей открылся в XIX веке; его коллекция посвящена искусству и истории Нидерландов.', 52.360000::numeric, 4.885200::numeric, 'Музеи', 'Нидерланды', 'Амстердам'),
    ('Голубая мечеть', 'Мечеть Султанахмет в историческом центре Стамбула.', 'Мечеть была построена в начале XVII века по распоряжению султана Ахмеда I.', 41.005400::numeric, 28.976800::numeric, 'Религиозные сооружения', 'Турция', 'Стамбул'),
    ('Собор Святой Софии', 'Исторический памятник архитектуры в Стамбуле.', 'Здание было построено как собор в VI веке, позднее использовалось как мечеть и музей; сейчас вновь действует как мечеть.', 41.008600::numeric, 28.980200::numeric, 'Религиозные сооружения', 'Турция', 'Стамбул'),
    ('Карлов мост', 'Средневековый каменный мост через Влтаву в Праге.', 'Строительство моста началось в XIV веке при короле Карле IV.', 50.086500::numeric, 14.411400::numeric, 'Архитектура', 'Чехия', 'Прага'),
    ('Кинкаку-дзи', 'Золотой павильон буддийского храмового комплекса в Киото.', 'Павильон был построен в XIV веке как загородная резиденция и позднее стал храмом.', 35.039400::numeric, 135.729200::numeric, 'Религиозные сооружения', 'Япония', 'Киото'),
    ('Токийская башня', 'Телевизионная и смотровая башня в Токио.', 'Башня открылась в 1958 году и была создана как телекоммуникационное сооружение.', 35.658600::numeric, 139.745400::numeric, 'Архитектура', 'Япония', 'Токио')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

SELECT count(*) AS seeded_attractions FROM attractions;
